use super::common::MockServer;
use milvus::v2::request::database::*;

#[tokio::test]
async fn database_interfaces_reach_rpc_server() {
    let server = MockServer::start().await;
    let client = &server.client;

    client
        .create_database(
            CreateDatabaseRequest::builder()
                .database_name("tenant")
                .properties(std::collections::HashMap::from([(
                    "initial".into(),
                    "true".into(),
                )]))
                .build()
                .expect("valid request"),
        )
        .await
        .unwrap();
    client.use_database("tenant").await.unwrap();
    assert_eq!(client.current_database(), "tenant");
    let databases = client
        .list_databases(
            ListDatabasesRequest::builder()
                .build()
                .expect("valid request"),
        )
        .await
        .unwrap();
    assert_eq!(databases.database_names().to_owned(), ["default", "tenant"]);

    let description = client
        .describe_database(
            DescribeDatabaseRequest::builder()
                .database_name("tenant")
                .build()
                .expect("valid request"),
        )
        .await
        .unwrap();
    assert_eq!(description.database_name().to_owned(), "tenant");
    assert_eq!(description.database_id().to_owned(), 20);
    assert_eq!(description.created_timestamp().to_owned(), 200);
    assert_eq!(
        description.properties().get("initial").unwrap().to_owned(),
        "true"
    );

    client
        .alter_database_properties(
            AlterDatabasePropertiesRequest::builder()
                .database_name("tenant")
                .property("key", "value")
                .build()
                .expect("valid request"),
        )
        .await
        .unwrap();
    let description = client
        .describe_database(
            DescribeDatabaseRequest::builder()
                .database_name("tenant")
                .build()
                .expect("valid request"),
        )
        .await
        .unwrap();
    assert_eq!(
        description.properties().get("key").unwrap().to_owned(),
        "value"
    );

    client
        .drop_database_properties(
            DropDatabasePropertiesRequest::builder()
                .database_name("tenant")
                .property_key("key")
                .build()
                .expect("valid request"),
        )
        .await
        .unwrap();
    let description = client
        .describe_database(
            DescribeDatabaseRequest::builder()
                .database_name("tenant")
                .build()
                .expect("valid request"),
        )
        .await
        .unwrap();
    assert!(!description.properties().contains_key("key"));
    assert_eq!(
        description.properties().get("initial").unwrap().to_owned(),
        "true"
    );

    client
        .drop_database(
            DropDatabaseRequest::builder()
                .database_name("tenant")
                .build()
                .expect("valid request"),
        )
        .await
        .unwrap();
    let databases = client
        .list_databases(
            ListDatabasesRequest::builder()
                .build()
                .expect("valid request"),
        )
        .await
        .unwrap();
    assert_eq!(databases.database_names().to_owned(), ["default"]);

    server.assert_request_contains("create_database", &["db_name: \"tenant\"", "initial"]);
    server.assert_request_contains("alter_database", &["db_name: \"tenant\""]);
    server.assert_request_contains("drop_database", &["db_name: \"tenant\""]);

    for rpc in [
        "create_database",
        "list_databases",
        "alter_database",
        "describe_database",
        "drop_database",
    ] {
        server.assert_called(rpc);
    }
    server.shutdown().await;
}

#[tokio::test]
async fn use_database_rejects_missing_database_without_switching() {
    let server = MockServer::start().await;
    let client = &server.client;

    let error = client
        .use_database("missing")
        .await
        .expect_err("selecting a missing database must fail");
    assert!(matches!(error, milvus::v2::error::Error::Server(_)));
    assert_eq!(client.current_database(), "default");
    server.assert_called("describe_database");

    client
        .create_database(
            CreateDatabaseRequest::builder()
                .database_name("tenant")
                .build()
                .expect("valid request"),
        )
        .await
        .unwrap();
    client
        .use_database("tenant")
        .await
        .expect("select existing database");
    assert_eq!(client.current_database(), "tenant");
    server.shutdown().await;
}

#[tokio::test]
async fn use_database_reset_to_default_does_not_issue_describe_database() {
    let server = MockServer::start().await;
    let client = &server.client;

    client
        .use_database("")
        .await
        .expect("reset to default without an RPC");
    assert_eq!(client.current_database(), "default");

    for rpc in ["describe_database", "list_databases"] {
        assert_eq!(
            server.service.call_count(rpc),
            0,
            "reset to default must not issue {rpc}"
        );
    }
    server.shutdown().await;
}
